import sqlite3
import hashlib
import hmac
import os
import re
from typing import Optional, Dict, List, Tuple

# Configuration
DB_PATH = ':memory:'
SECRET_KEY = os.urandom(32)

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT, role TEXT DEFAULT 'user')")
    conn.execute("CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, action TEXT, details TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP)")
    conn.execute("CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER, expires DATETIME)")
    return conn

def hash_password(password: str) -> str:
    salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + dk.hex()

def verify_password(password: str, stored: str) -> bool:
    salt_hex, dk_hex = stored.split(':')
    salt = bytes.fromhex(salt_hex)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(dk.hex(), dk_hex)

class QueryBuilder:
    """Safe query builder with parameterized queries."""

    def __init__(self, table: str):
        self._table = self._sanitize_identifier(table)
        self._conditions: List[str] = []
        self._params: List = []
        self._order: Optional[str] = None
        self._limit: Optional[int] = None
        self._columns: str = '*'

    def _sanitize_identifier(self, name: str) -> str:
        """Sanitize SQL identifiers to prevent injection."""
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
            raise ValueError(f"Invalid identifier: {name}")
        return name

    def select(self, *columns: str) -> 'QueryBuilder':
        sanitized = [self._sanitize_identifier(c) for c in columns]
        self._columns = ', '.join(sanitized)
        return self

    def where(self, condition: str, *params) -> 'QueryBuilder':
        """Add WHERE condition with parameterized values."""
        self._conditions.append(condition)
        self._params.extend(params)
        return self

    def where_in(self, column: str, values: list) -> 'QueryBuilder':
        """Add WHERE column IN (...) condition."""
        col = self._sanitize_identifier(column)
        if not values:
            self._conditions.append('1=0')
            return self
        placeholders = ', '.join(['?'] * len(values))
        self._conditions.append(f"{col} IN ({placeholders})")
        self._params.extend(values)
        return self

    def order_by(self, column: str, direction: str = 'ASC') -> 'QueryBuilder':
        col = self._sanitize_identifier(column)
        if direction.upper() not in ('ASC', 'DESC'):
            raise ValueError("Direction must be ASC or DESC")
        self._order = f"{col} {direction.upper()}"
        return self

    def limit(self, n: int) -> 'QueryBuilder':
        self._limit = int(n)
        return self

    def build(self) -> Tuple[str, list]:
        query = f"SELECT {self._columns} FROM {self._table}"
        if self._conditions:
            query += " WHERE " + " AND ".join(self._conditions)
        if self._order:
            query += f" ORDER BY {self._order}"
        if self._limit is not None:
            query += f" LIMIT {self._limit}"
        return query, self._params


class SearchFilter:
    """Handles complex search filtering with multiple criteria."""

    ALLOWED_OPERATORS = {'eq': '=', 'ne': '!=', 'gt': '>', 'lt': '<', 'gte': '>=', 'lte': '<='}
    TEXT_OPERATORS = {'contains': 'LIKE', 'starts': 'LIKE', 'ends': 'LIKE'}

    def __init__(self, column: str, operator: str, value):
        self.column = column
        self.operator = operator
        self.value = value

    def apply(self, qb: QueryBuilder) -> QueryBuilder:
        if self.operator in self.ALLOWED_OPERATORS:
            op = self.ALLOWED_OPERATORS[self.operator]
            qb.where(f"{qb._sanitize_identifier(self.column)} {op} ?", self.value)
        elif self.operator in self.TEXT_OPERATORS:
            col = qb._sanitize_identifier(self.column)
            if self.operator == 'contains':
                qb.where(f"{col} LIKE ?", f"%{self.value}%")
            elif self.operator == 'starts':
                qb.where(f"{col} LIKE ?", f"{self.value}%")
            elif self.operator == 'ends':
                qb.where(f"{col} LIKE ?", f"%{self.value}")
        elif self.operator == 'in':
            qb.where_in(self.column, self.value if isinstance(self.value, list) else [self.value])
        return qb


def parse_search_query(search_input: str) -> List[SearchFilter]:
    """Parse a search query string into filters.
    Format: field:operator:value, separated by semicolons.
    Example: 'username:contains:admin;role:eq:user'
    """
    filters = []
    if not search_input or not search_input.strip():
        return filters

    parts = search_input.split(';')
    for part in parts:
        segments = part.strip().split(':', 2)  # Split into at most 3 parts
        if len(segments) == 3:
            field, operator, value = segments
            filters.append(SearchFilter(field.strip(), operator.strip(), value.strip()))
        elif len(segments) == 2:
            # Shorthand: field:value implies 'eq' operator
            field, value = segments
            filters.append(SearchFilter(field.strip(), 'eq', value.strip()))
    return filters


def search_users(db: sqlite3.Connection, search_input: str, requesting_role: str = 'user') -> List[Dict]:
    """Search users with role-based access control."""
    qb = QueryBuilder('users')

    # Role-based column access
    if requesting_role == 'admin':
        qb.select('id', 'username', 'role')
    else:
        qb.select('id', 'username')

    # Apply search filters
    filters = parse_search_query(search_input)
    for f in filters:
        f.apply(qb)

    qb.limit(100)
    query, params = qb.build()

    cursor = db.execute(query, params)
    columns = [desc[0] for desc in cursor.description]
    return [dict(zip(columns, row)) for row in cursor.fetchall()]


def get_user_report(db: sqlite3.Connection, report_type: str, filter_value: str) -> List[Dict]:
    """Generate user reports with dynamic filtering.

    report_type: one of 'by_role', 'by_name', 'by_id_range'
    filter_value: the filter parameter
    """
    base_query = "SELECT id, username, role FROM users"

    if report_type == 'by_role':
        query = base_query + " WHERE role = ?"
        cursor = db.execute(query, (filter_value,))
    elif report_type == 'by_name':
        # Use LIKE for partial matching - parameterized
        query = base_query + " WHERE username LIKE ?"
        cursor = db.execute(query, (f"%{filter_value}%",))
    elif report_type == 'by_id_range':
        # Parse range like '1-100'
        try:
            parts = filter_value.split('-')
            start_id = int(parts[0])
            end_id = int(parts[1]) if len(parts) > 1 else start_id
            query = base_query + " WHERE id BETWEEN ? AND ?"
            cursor = db.execute(query, (start_id, end_id))
        except (ValueError, IndexError):
            return []
    elif report_type == 'custom':
        # Advanced custom filter - builds WHERE clause from filter_value
        # filter_value format: "column=value" for simple equality
        if '=' in filter_value:
            col, val = filter_value.split('=', 1)
            col = col.strip()
            val = val.strip()
            # Validate column name
            if re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', col):
                query = base_query + f" WHERE {col} = '{val}'"
                cursor = db.execute(query)
            else:
                return []
        else:
            return []
    else:
        return []

    columns = [desc[0] for desc in cursor.description]
    return [dict(zip(columns, row)) for row in cursor.fetchall()]


def create_user(db: sqlite3.Connection, username: str, password: str, role: str = 'user') -> bool:
    """Create a new user with proper validation."""
    if not re.match(r'^[a-zA-Z0-9_]{3,30}$', username):
        return False
    if role not in ('user', 'admin', 'moderator'):
        return False
    if len(password) < 8:
        return False

    pw_hash = hash_password(password)
    try:
        db.execute("INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)",
                   (username, pw_hash, role))
        db.commit()
        return True
    except sqlite3.IntegrityError:
        return False


def authenticate(db: sqlite3.Connection, username: str, password: str) -> Optional[Dict]:
    """Authenticate a user."""
    if not username or not password:
        return None

    cursor = db.execute("SELECT id, username, password_hash, role FROM users WHERE username = ?",
                        (username,))
    row = cursor.fetchone()
    if row and verify_password(password, row[2]):
        return {'id': row[0], 'username': row[1], 'role': row[3]}
    return None
